def check(raw,record):
    if (len(raw)>=100000 or len(raw)!=record["bytes"]
            or hashlib.sha256(raw).hexdigest()!=record["sha256"]):
        raise ValueError("The complete text identity differs: "+record["name"])
    return raw.decode("utf-8")


def change(text,item,inverse=False):
    old=item["new"] if inverse else item["old"]
    new=item["old"] if inverse else item["new"]
    if text.count(old)!=item["count"]:
        raise ValueError("The exact full-source replacement count differs")
    return text.replace(old,new)


def remap(value,old,new):
    if isinstance(value,str):
        return value.replace(old,new)
    if isinstance(value,list):
        return [remap(v,old,new) for v in value]
    if isinstance(value,dict):
        return {k.replace(old,new):remap(v,old,new) for k,v in value.items()}
    return value


def complete_plan_parent_relation(original,new,item):
    old=json.loads(original)
    current=json.loads(new)
    inverse=remap(current["steps"],item["new_output_directory"],item["old_output_directory"])
    inverse[0]["script"]=old["steps"][0]["script"]
    inverse[0]["id"]=old["steps"][0]["id"]
    inverse[0]["scope"]=old["steps"][0]["scope"]
    flag="--report" if "--report" in inverse[0]["args"] else "--normal-report"
    before=old["steps"][0]["args"]
    inverse[0]["args"][inverse[0]["args"].index(flag)+1]=before[before.index(flag)+1]
    if inverse!=old["steps"]:
        raise ValueError("Every original numeric parameter, selector and output declaration must remain")
    if current["actual_field_point_or_fee_values_assumed"] is not False:
        raise ValueError("The successor does not prefill a scientific point or accurate fee")
    return True


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source-directory",type=Path,required=True)
    parser.add_argument("--parameter-directory",type=Path,required=True)
    parser.add_argument("--output-source-directory",type=Path,required=True)
    parser.add_argument("--output-parameter-directory",type=Path,required=True)
    args=parser.parse_args()
    origins=args.source_directory.resolve()
    parameters=args.parameter_directory.resolve()
    source_target=args.output_source_directory.resolve()
    parameter_target=args.output_parameter_directory.resolve()
    if origins==source_target or parameters==parameter_target:
        raise ValueError("Use independent complete output directories")
    inputs=[]
    outputs=[]
    for item in DATA["source_derivations"]:
        path=origins/item["parent"]["name"]
        original=check(path.read_bytes(),item["parent"])
        text=original
        for patch in item["patches"]:
            text=change(text,patch)
        check(text.encode("utf-8"),item["output"])
        inverse=text
        for patch in reversed(item["patches"]):
            inverse=change(inverse,patch,True)
        if inverse!=original:
            raise ValueError("The entire original mathematical/source body was not retained")
        inputs.append((path,item["parent"]))
        outputs.append((source_target/item["output"]["name"],text.encode("utf-8"),item["output"]))
    for item in DATA["plans"]:
        path=parameters/item["parent"]["name"]
        original=check(path.read_bytes(),item["parent"])
        raw=item["source"].encode("utf-8")
        text=check(raw,item["output"])
        complete_plan_parent_relation(original,text,item)
        inputs.append((path,item["parent"]))
        outputs.append((parameter_target/item["output"]["name"],raw,item["output"]))
    for path,raw,record in outputs:
        if path.exists() and path.read_bytes()!=raw:
            raise ValueError("Do not replace another full source or parameter file")
    for path,raw,record in outputs:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_bytes(raw)
        check(path.read_bytes(),record)
    for path,record in inputs:
        check(path.read_bytes(),record)
    print(json.dumps(dict(schema=DATA["schema"],complete_output_records=[r for _,_,r in outputs],
        numerical_execution=False,old_M_queue_or_sources_modified=False,
        scientific_admission_gate=False),sort_keys=True))


if __name__=="__main__":
    main()
